using Microsoft.AspNetCore.Components.Authorization;
using Microsoft.AspNetCore.Identity;
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Pages;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Components;
using ShipmentTracker.Components.Account;
using ShipmentTracker.Data;
using ShipmentTracker.Services;

var builder = WebApplication.CreateBuilder(args);

// Add services to the container.
builder.Services.AddRazorComponents()
    .AddInteractiveServerComponents()
    .AddInteractiveWebAssemblyComponents()
    .AddAuthenticationStateSerialization();

builder.Services.AddCascadingAuthenticationState();
builder.Services.AddScoped<IdentityRedirectManager>();
builder.Services.AddScoped<AuthenticationStateProvider, IdentityRevalidatingAuthenticationStateProvider>();

builder.Services.AddAuthentication(options =>
    {
        options.DefaultScheme = IdentityConstants.ApplicationScheme;
        options.DefaultSignInScheme = IdentityConstants.ExternalScheme;
    })
    .AddIdentityCookies();

var connectionString = builder.Configuration.GetConnectionString("DefaultConnection") ?? throw new InvalidOperationException("Connection string 'DefaultConnection' not found.");
builder.Services.AddDbContext<ApplicationDbContext>(options =>
    options.UseSqlite(connectionString));
builder.Services.AddDatabaseDeveloperPageExceptionFilter();

builder.Services.AddIdentityCore<ApplicationUser>(options =>
    {
        options.SignIn.RequireConfirmedAccount = true;
        options.Stores.SchemaVersion = IdentitySchemaVersions.Version3;
    })
    .AddRoles<IdentityRole>()
    .AddEntityFrameworkStores<ApplicationDbContext>()
    .AddSignInManager()
    .AddDefaultTokenProviders();

builder.Services.AddSingleton<IEmailSender<ApplicationUser>, IdentityNoOpEmailSender>();

builder.Services.AddScoped<IShipmentService, ShipmentServiceServer>();

var app = builder.Build();

// Seed database
using (var scope = app.Services.CreateScope())
{
    var services = scope.ServiceProvider;
    var db = services.GetRequiredService<ApplicationDbContext>();
    db.Database.Migrate();

    var roleManager = services.GetRequiredService<RoleManager<IdentityRole>>();
    if (!await roleManager.RoleExistsAsync("Dispatcher"))
    {
        await roleManager.CreateAsync(new IdentityRole("Dispatcher"));
    }

    var userManager = services.GetRequiredService<UserManager<ApplicationUser>>();

    // Seed dispatcher user
    if (await userManager.FindByEmailAsync("dispatcher@shipmenttracker.com") is null)
    {
        var dispatcher = new ApplicationUser
        {
            UserName = "dispatcher@shipmenttracker.com",
            Email = "dispatcher@shipmenttracker.com",
            EmailConfirmed = true
        };
        await userManager.CreateAsync(dispatcher, "Dispatcher1!");
        await userManager.AddToRoleAsync(dispatcher, "Dispatcher");
    }

    // Seed customer user
    if (await userManager.FindByEmailAsync("customer@example.com") is null)
    {
        var customer = new ApplicationUser
        {
            UserName = "customer@example.com",
            Email = "customer@example.com",
            EmailConfirmed = true
        };
        await userManager.CreateAsync(customer, "Customer1!");
    }

    // Seed shipments
    if (!db.Shipments.Any())
    {
        db.Shipments.AddRange(
            new ShipmentEntity
            {
                TrackingNumber = "TRK-001",
                Origin = "New York, NY",
                Destination = "Los Angeles, CA",
                Status = (int)ShipmentStatus.InTransit,
                ShippedDate = DateTime.UtcNow.AddDays(-3),
                EstimatedDelivery = DateTime.UtcNow.AddDays(2),
                CustomerEmail = "customer@example.com",
                Description = "Electronics - Laptop"
            },
            new ShipmentEntity
            {
                TrackingNumber = "TRK-002",
                Origin = "Chicago, IL",
                Destination = "Houston, TX",
                Status = (int)ShipmentStatus.Delivered,
                ShippedDate = DateTime.UtcNow.AddDays(-7),
                EstimatedDelivery = DateTime.UtcNow.AddDays(-2),
                ActualDelivery = DateTime.UtcNow.AddDays(-2),
                CustomerEmail = "customer@example.com",
                Description = "Books - Textbooks"
            },
            new ShipmentEntity
            {
                TrackingNumber = "TRK-003",
                Origin = "Seattle, WA",
                Destination = "Denver, CO",
                Status = (int)ShipmentStatus.Pending,
                ShippedDate = DateTime.UtcNow,
                EstimatedDelivery = DateTime.UtcNow.AddDays(5),
                CustomerEmail = "customer@example.com",
                Description = "Clothing - Winter Jacket"
            },
            new ShipmentEntity
            {
                TrackingNumber = "TRK-004",
                Origin = "Miami, FL",
                Destination = "Atlanta, GA",
                Status = (int)ShipmentStatus.OutForDelivery,
                ShippedDate = DateTime.UtcNow.AddDays(-2),
                EstimatedDelivery = DateTime.UtcNow,
                CustomerEmail = "customer@example.com",
                Description = "Furniture - Office Chair"
            },
            new ShipmentEntity
            {
                TrackingNumber = "TRK-005",
                Origin = "Boston, MA",
                Destination = "Philadelphia, PA",
                Status = (int)ShipmentStatus.Delayed,
                ShippedDate = DateTime.UtcNow.AddDays(-5),
                EstimatedDelivery = DateTime.UtcNow.AddDays(1),
                CustomerEmail = "dispatcher@shipmenttracker.com",
                Description = "Medical Supplies"
            }
        );
        await db.SaveChangesAsync();
    }
}

// Configure the HTTP request pipeline.
if (app.Environment.IsDevelopment())
{
    app.UseWebAssemblyDebugging();
    app.UseMigrationsEndPoint();
}
else
{
    app.UseExceptionHandler("/Error", createScopeForErrors: true);
}
app.UseStatusCodePagesWithReExecute("/not-found", createScopeForStatusCodePages: true);
app.UseAntiforgery();

// API Endpoints
app.MapGet("/api/shipments", async (IShipmentService service) =>
{
    var shipments = await service.GetAllShipmentsAsync();
    return Results.Ok(shipments);
}).RequireAuthorization(policy => policy.RequireRole("Dispatcher"));

app.MapGet("/api/shipments/track/{trackingNumber}", async (string trackingNumber, IShipmentService service) =>
{
    var shipment = await service.GetShipmentByTrackingNumberAsync(trackingNumber);
    return shipment is null ? Results.NotFound() : Results.Ok(shipment);
}).RequireAuthorization();

app.MapGet("/api/shipments/my", async (HttpContext context, IShipmentService service) =>
{
    var email = context.User.Identity?.Name ?? string.Empty;
    var shipments = await service.GetShipmentsByCustomerAsync(email);
    return Results.Ok(shipments);
}).RequireAuthorization();

app.MapPut("/api/shipments/{id}/status", async (int id, ShipmentStatus status, IShipmentService service) =>
{
    var shipment = await service.UpdateShipmentStatusAsync(id, status);
    return Results.Ok(shipment);
}).RequireAuthorization(policy => policy.RequireRole("Dispatcher"));

app.MapStaticAssets();
app.MapRazorComponents<App>()
    .AddInteractiveServerRenderMode()
    .AddInteractiveWebAssemblyRenderMode()
    .AddAdditionalAssemblies(typeof(ShipmentTracker.Client._Imports).Assembly);

// Add additional endpoints required by the Identity /Account Razor components.
app.MapAdditionalIdentityEndpoints();

app.Run();

